-- #788: hockey's reference data, a separate migration from the one that adds HOCKEY to the sport
-- enum: a new enum value cannot be used in the transaction that added it.
--
-- The sports row: a team competes, and an event is played as MATCHES. Idempotent on the `sport`
-- unique, as the other sports' rows are.
INSERT INTO "sports" ("id", "sport", "participant_type", "tournament_format", "created_at", "updated_at")
VALUES (gen_random_uuid(), 'HOCKEY', 'TEAM', 'MATCHES', NOW(), NOW())
ON CONFLICT ("sport") DO NOTHING;

-- Its sport leagues, reference data because their contest templates name them. Every bracket is
-- fixed. The NHL and PWHL play best-of-seven and best-of-five series, each one bracket match whose
-- scores are the games won; the NCAA tournaments are single games. The NHL, the PWHL and the
-- women's tournament name their own rounds (none reads the sport's, the men's tournament's), and
-- the PWHL's four teams start on two tiers. Idempotent on the (sport_id, name) unique: an admin
-- who already created a league keeps their row, and gets the round names and tier count.
INSERT INTO "sport_leagues" ("id", "sport_id", "name", "bracket_advancement", "round_names", "tier_count", "is_active", "created_at", "updated_at")
SELECT gen_random_uuid(), s."id", league."name", 'FIXED', league."round_names", league."tier_count", TRUE, NOW(), NOW()
FROM "sports" s
CROSS JOIN (VALUES
  ('NHL', ARRAY['First Round', 'Second Round', 'Conference Finals', 'Stanley Cup Final']::text[], NULL::int),
  ('PWHL', ARRAY['Semifinals', 'Walter Cup Finals']::text[], 2),
  ('NCAA Division I Men', ARRAY[]::text[], NULL::int),
  ('NCAA Division I Women', ARRAY['Quarterfinals', 'Frozen Four', 'National Championship']::text[], NULL::int)
) AS league("name", "round_names", "tier_count")
WHERE s."sport" = 'HOCKEY'
ON CONFLICT ("sport_id", "name") DO UPDATE SET "round_names" = EXCLUDED."round_names", "tier_count" = EXCLUDED."tier_count";

-- Each league's contest templates, named and defaulted as `rules/ux-rules.md` §12 says: one
-- default per format, ahead of its variations, all for a KNOCKOUT. Roster picks and brackets are
-- scored by knockout round points (Doubling, with and without the seed-difference upset bonus),
-- their round values matching the league's round count; survivor and squares score by their own
-- rules. Squares runs on one game, so only the college tournaments, whose title game is one game,
-- have a squares template; an NHL or PWHL final is a series.
INSERT INTO "contest_config_templates" (
  "id", "sport", "sport_league_id", "event_type", "contest_type", "selection_type", "template_key",
  "name", "description", "sort_order", "is_default", "active", "config_json", "schema_version", "updated_at"
)
SELECT
  gen_random_uuid(), 'HOCKEY', l."id", 'KNOCKOUT', preset."contest_type"::"PrismaContestFormat",
  preset."selection_type"::"PrismaSelectionType", preset."template_key", preset."name", preset."description",
  preset."sort_order", preset."is_default", TRUE, preset."config_json"::jsonb, 1, NOW()
FROM (VALUES
  ('NHL', 'TIERED', 'ROSTER', 'nhl-tiered-doubling', 'Tiered: 1 team per tier, doubling points', 'Pick one team from each of the four tiers. A series win scores 1 point in the First Round, doubling each round to 8 in the Stanley Cup Final.', 1, TRUE, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 4, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8], "upsetBonus": {"rule": "NONE"}}}}'),
